EXPECTED_SHA256 = "a1c0efa85152a4cd2d83a3ec3a4a8b951ed51a33d74738893d1e2e41542aaa07"
ROOT = Path(__file__).resolve().parent / "site_files"


def prepare_files():
    data = base64.b64decode(PAYLOAD)
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        raise RuntimeError("The bundled website is damaged. Download this file again.")
    marker = ROOT / ".bundle.sha256"
    if marker.exists() and marker.read_text(encoding="ascii") == EXPECTED_SHA256:
        return
    ROOT.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        for info in archive.infolist():
            target = (ROOT / info.filename).resolve()
            if not target.is_relative_to(ROOT.resolve()):
                raise RuntimeError("Invalid path in website bundle")
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(info))
    marker.write_text(EXPECTED_SHA256, encoding="ascii")


def ensure_requirements():
    missing = []
    for line in (ROOT / "requirements.txt").read_text(encoding="utf-8").splitlines():
        if not line or line.startswith("#"):
            continue
        package, version = line.split("==", 1)
        try:
            installed = metadata.version(package)
        except metadata.PackageNotFoundError:
            installed = None
        if installed != version:
            missing.append(f"{package}=={version}")
    if missing:
        print("Installing the website requirements:", ", ".join(missing), flush=True)
        subprocess.run([sys.executable, "-m", "pip", "install", "-r", str(ROOT / "requirements.txt")], check=True)


def main():
    parser = argparse.ArgumentParser(description="Run the local Demand Forecast Lab website")
    parser.add_argument("--port", type=int, default=8767)
    parser.add_argument("--no-browser", action="store_true")
    parser.add_argument("--check", action="store_true", help="Unpack and check files, then exit")
    args = parser.parse_args()
    if sys.version_info < (3, 13):
        raise SystemExit("Python 3.13 is required. Install it, then run this file again.")
    prepare_files()
    if args.check:
        print("Website source unpacked and verified in", ROOT)
        return
    ensure_requirements()
    print("Starting the website at http://127.0.0.1:%s/" % args.port, flush=True)
    command = [sys.executable, str(ROOT / "server.py"), "--port", str(args.port)]
    if not args.no_browser:
        command.append("--open")
    subprocess.run(command, cwd=ROOT, check=True)


if __name__ == "__main__":
    try:
        main()
    except (OSError, subprocess.CalledProcessError) as exc:
        print("Website setup failed:", exc)
        print("Check Python 3.13 and internet access, then run this file again.")
        raise
